class _N:
    def __init__(self, v, n=None): self.v, self.n = v, n

class ChainList:
    def __init__(self):
        self.d = _N(0); self.size = 0
    def _before(self, i):
        c = self.d
        for _ in range(i): c = c.n
        return c
    def get(self, index: int) -> int:
        if index < 0 or index >= self.size: return -1
        return self._before(index).n.v
    def addAtHead(self, val: int) -> None:
        self.addAtIndex(0, val)
    def addAtTail(self, val: int) -> None:
        self.addAtIndex(self.size, val)
    def addAtIndex(self, index: int, val: int) -> None:
        if index > self.size: return
        p = self._before(index); p.n = _N(val, p.n); self.size += 1
    def deleteAtIndex(self, index: int) -> None:
        if index < 0 or index >= self.size: return
        p = self._before(index); p.n = p.n.n; self.size -= 1

